{"packet_id":"D029-01","doc_id":"D029","jurisdiction":"Cambridge, MA","category":"screening_restrictions","lifecycle":"enacted","title":"Reasonable, uniformly applied tenant-selection standard","requirement":"Landlords, sellers and rental agents may use any reasonable standard to select applicants, but it must be applied equally and uniformly to all; selection may consider ability to pay rent and care for the apartment.","key_value":null,"coverage_conditions":"Real estate transactions under the Fair Housing Ordinance, including renting an apartment; 2-family owner-occupied dwellings are exempt.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exemption for 2-family dwellings when the owner lives there"},"exemptions":"2-family dwellings when the owner lives there.","penalty":null,"effective_date":null,"citation":"Cambridge Fair Housing Ordinance ch. 14.04","quoted_span":"Under the law, landlords, sellers and rental agents may use any reasonable standard to determine which applicants are selected, as long as that standard is applied equally and uniformly to all applicants.","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
